sed -i '238,255d' app/src/main/java/com/example/data/repository/FrictionRepository.kt
sed -i '236a \    suspend fun saveAppClassification(pkg: String, name: String, classification: String) {\n        val entry = com.example.data.model.AppClassification(pkg, name, classification)\n        dao.insertAppClassification(entry)\n        val uid = currentUserUid\n        if (uid != null) {\n            firestoreService.db.collection("users").document(uid)\n                .collection("appClassifications").document(pkg.replace("/", "_"))\n                .set(mapOf(\n                    "packageName" to pkg,\n                    "appName" to name,\n                    "classification" to classification,\n                    "updatedAt" to System.currentTimeMillis()\n                ), SetOptions.merge())\n        }\n    }' app/src/main/java/com/example/data/repository/FrictionRepository.kt
